W=float(sys.argv[1]) if len(sys.argv)>1 else 60
S=W/math.sqrt(3); LON0=15; LAT0=72.0
def unproj(x,y):
    la=LAT0-y/111; lo=LON0+x/(111*math.cos(math.radians(la))); return lo,la
X0=-3800; X1=3200; Y1=(LAT0-34)*111
cols=int((X1-X0)/W)+1; rows=int(Y1/(1.5*S))+1
grid=[['.']*cols for _ in range(rows)]
counts={}
for r in range(rows):
    for c in range(cols):
        x=X0+W*(c+0.5*(r&1)); y=1.5*S*r
        lo,la=unproj(x,y)
        for code,_id,name,polys,play in ALL:
            if any(inside((lo,la),p) for p in polys):
                grid[r][c]=code; break
        else:
            if inside((lo,la),AFR): grid[r][c]='~'   # other continent
# Tiny countries get at least one cell, at their capital
CAP={'L':(9.52,47.14),'U':(6.13,49.61),'W':(14.51,46.06),'w':(33.4,35.1),'o':(21.1,42.65),'p':(19.26,42.44),'n':(21.43,41.99),'m':(19.82,41.33),'e':(24.75,59.44),'d':(9.5,56.0),'i':(28.86,47.0)}
def cell_of(lo,la):
    y=(LAT0-la)*111; x=(lo-LON0)*111*math.cos(math.radians(la))
    r=round(y/(1.5*S)); c=round((x-X0)/W-0.5*(r&1)); return r,c
for code,(lo,la) in CAP.items():
    if not any(code in row for row in grid):
        r,c=cell_of(lo,la); grid[r][c]=code
# trim
used=[(r,c) for r in range(rows) for c in range(cols) if grid[r][c]!='.']
r0=min(r for r,_ in used); r0-=r0%2; r1=max(r for r,_ in used); c0=min(c for _,c in used); c1=max(c for _,c in used)
out=[''.join(grid[r][c0:c1+1]) for r in range(r0,r1+1)]
from collections import Counter
cnt=Counter(ch for l in out for ch in l)
print(len(out),len(out[0]),sum(v for k,v in cnt.items() if k not in '.~'))
print({c:cnt.get(c,0) for c,*_ in ALL})
for l in out[::2]: print(l[::2])
data=dict(w=W,rows=out,countries=[dict(code=c,id=i,name=n,playable=bool(pl)) for c,i,n,_,pl in ALL])
json.dump(data,open('europe.json','w'),ensure_ascii=False)
